#!/usr/bin/env python3
"""
Round 120b (culprits-tiles-more), 1 October 2026. Upload after round119b_tiles.py.

- scripts/methane_culprits.py (new): methane plumes and the 50 largest sites
  seen by the UN Environment Programme's methane observatory, and the sites
  Climate TRACE names owners for, with the owners ranked by their methane.
- scripts/fertiliser_by_crop.py (new): the nitrogen fertiliser each crop gets,
  country by country (IFA surveys, Ludemann et al. 2022).
- scripts/edgar_fgases.py: every F-gas together in tonnes of CO2 equivalent
  (IPCC AR5 warming potentials), as a map and as raised ground. Runs by hand.

Every file is written whole, and only if it differs.
"""
import base64, pathlib

FILES = {
    'scripts/methane_culprits.py': '',
    'scripts/fertiliser_by_crop.py': '',
    'scripts/edgar_fgases.py': '',
}


def main():
    for name, data in FILES.items():
        p = pathlib.Path(name)
        new = base64.b64decode(data)
        if p.exists() and p.read_bytes() == new:
            print(f"  {name}: already as written")
            continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(new)
        print(f"  {name}: written")


if __name__ == "__main__":
    main()
